// De agent verwacht de velden van de chat trigger. Die zet deze node terug,
// met de vastgestelde identiteit erbij. Zonder dit zou de agent het antwoord
// van Microsoft als vraag voorgeschoteld krijgen.
const trigger = $('When chat message received').first().json;
const wie = $('Wie ben jij').first().json;

return [{
  json: {
    ...trigger,
    ...(trigger.body ?? {}),
    verified_oid: wie.id ?? '',
    verified_naam: wie.displayName ?? '',
    verified_email: wie.mail ?? wie.userPrincipalName ?? '',
  },
}];

